// ── PARALLEL GENERATE (replaces serial Loop + Call V01 each) ──────────────────
// Fires every claimed post's /api/image/generate (or /generate-video) call
// CONCURRENTLY with bounded parallelism, then PATCHes each result to the DB.
// The Sharp Arabic overlay + Supabase upload happen INSIDE /api/image/generate
// (server side), so calling it directly keeps Hard Rule #3 + C2PA intact.
// ~60 images ÷ CONCURRENCY × ~15s  →  ~2-3 min instead of ~22 min serial.
const crypto = require('crypto');
const SUPABASE_URL = 'https://redzmrlzhxkkpgcokgvl.supabase.co';
const SERVICE_KEY  = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJlZHptcmx6aHhra3BnY29rZ3ZsIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NzUzMDE5MiwiZXhwIjoyMDkzMTA2MTkyfQ.JK_Vctncdz90VUxnRXVnwysl6P6XgKbJ2-a5Zf3qgpo';
const SECRET       = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const API_HOST     = 'https://unwieldable-mavis-unbacked.ngrok-free.dev';
const CONCURRENCY  = 5;     // 5 in flight. Math: image≈12s, video≈25s (keyframe sync).
                             // CONCURRENCY=8 caused all 10 posts to start simultaneously
                             // → video posts blocked slots for 25s → image posts piled up
                             // → some HTTP calls still in flight when n8n 60s kill hit
                             // → those posts left as visual_processing zombies forever.
                             // 5 concurrent: 5 start, slot frees at ~12s, next 5 start,
                             // wall-clock ≈ 24s for 8 image + 2 video → safe within 50s deadline.

const http = async (opts) => {
  try { const r = await this.helpers.httpRequest({ ...opts, returnFullResponse:true });
        return { ok:(r.statusCode>=200&&r.statusCode<300), status:r.statusCode, body:r.body }; }
  catch (e) { const b=e&&e.response&&e.response.body; return { ok:false, status:(e&&e.statusCode)||0, body: b!==undefined?b:{error:(e&&e.message)} }; }
};
const sign = (s) => crypto.createHmac('sha256', SECRET).update(s).digest('hex');
const patch = (post_id, fields) => http({
  method:'PATCH', url: SUPABASE_URL+'/rest/v1/calendar_posts?post_id=eq.'+post_id,
  headers:{ apikey:SERVICE_KEY, Authorization:'Bearer '+SERVICE_KEY, 'Content-Type':'application/json', Prefer:'return=minimal' },
  body: fields, json:true, timeout:20000,
});

// ── route + payload builder (ported from 'Map Post -> V01 Input') ──
function buildReq(post) {
  // FAIL-SAFE: a missing CCO score must route to HOLD (human review), never
  // default to 75 (=CLEAN). scoreKnown distinguishes 'no score' from a real low one.
  const scoreKnown = typeof post.cco_score === 'number';
  const score = scoreKnown ? post.cco_score : null;
  const forcedReview = post.requires_human_review === true || !!post.hold_reason || !scoreKnown;
  let route;
  if (forcedReview) route='HOLD';
  else if (post.negpat_flag==='HARD_BLOCK') route='HOLD';
  else if (score<50) route='HOLD';
  else if (score<75 || post.negpat_flag==='STRONG_WARN' || post.brave_route_flag) route='WATERMARK';
  else route='CLEAN';
  const isVideo = (post.format==='video')||(post.format_tier==='video');
  const month = (post.posting_time||'').substring(0,7) || '2026-06';
  const GRAVITY={ south:'bottom-right', north:'top-right', center:'center-right' };
  const hexes = ((post.primary_color_hex||'')+' '+(post.brand_color_palette||'')).match(/#[0-9a-fA-F]{3,8}/g)||[];
  const palette_hex = [...new Set(hexes)].length ? [...new Set(hexes)] : ['#000000','#ffffff'];
  const prompt_en = post.image_prompt_en || post.visual_brief_en || 'product lifestyle photography, clean background, natural lighting';
  const payload = {
    prompt_en, visual_brief_en: prompt_en,
    brand_name_ar: post.brand_name_ar || '', headline_ar: post.caption_ar || '',
    caption_ar: post.caption_ar || '', dialect: post.dialect || 'MSA_formal',
    channel: post.channel || 'Instagram',
    objective: post.content_type==='offer' ? 'conversion' : 'awareness',
    confidence_flag: route==='WATERMARK' ? 'watermark_required' : 'clean',
    cost_constraint: 'normal', palette_hex,
    month, score, confidence_score: score,
    expected_media_type: isVideo ? 'video' : 'image',
    chain_id: post.chain_id || null,
    chain_context: { product_descriptor: post.product_descriptor || 'product',
      brand_color_palette: post.brand_color_palette || '', occasion_visual_motif: post.occasion_visual_motif || '' },
    layout: GRAVITY[post.sharp_text_gravity || 'south'] || 'bottom-right',
    first_ever_post: (Number(post.total_calendars_generated)||0)===0,
  };
  const body = JSON.stringify({ flow_id:'N8N-V01', brand_id: post.brand_id, post_id: post.post_id, payload });
  // ALL posts go to /api/image/generate — it handles async video internally via
  // expected_media_type='video' + NEXT_PUBLIC_APP_URL webhook. /api/image/generate-video
  // is a legacy minimal route that lacks brand_name_ar, dialect, palette_hex, score,
  // confidence_flag and does its own incomplete prompt assembly — sending video posts
  // there caused irrelevant images (red doors etc.) because the brief was ignored.
  const url = API_HOST+'/api/image/generate';
  return { post, route, score, isVideo, month, url, body };
}

// ── process ONE post: call API, then PATCH DB ──
async function processOne(post) {
  const req = buildReq(post);
  const reqId = crypto.randomUUID();
  console.log('[Worker][DEBUG] post='+post.post_id+' isVideo='+req.isVideo+' url='+req.url+' prompt_len='+(post.image_prompt_en||'').length+' prompt_preview="'+(post.image_prompt_en||'').slice(0,120)+'"');
  // Per-call deadline guard: if the node-level deadline already passed by the time
  // a slot starts this post (can happen if prior processOne() ran long), immediately
  // release back to pending_visual instead of starting a new 38s HTTP call.
  if (Date.now() - START > DEADLINE_MS) {
    await patch(post.post_id, { status:'pending_visual', claimed_at:null }).catch(()=>{});
    released.push(post.post_id);
    return { post_id:post.post_id, action:'released_deadline' };
  }
  const res = await http({
    method:'POST', url: req.url,
    headers:{ 'Content-Type':'application/json', 'x-n8n-signature': sign(req.body),
              'x-n8n-request-id': reqId, 'x-n8n-timestamp': new Date().toISOString() },
    body: req.body, timeout: 38000,  // 38s hard cap per call. Image ≈ 12s, video (keyframe) ≈ 25s.
                                     // 38s ensures a timed-out call returns (error-caught) before
                                     // the DEADLINE_MS=42s guard fires, giving the guard time to
                                     // patch remaining posts back to pending_visual before n8n kills
                                     // the node at 60s. Previous 45s was too close to the 50s deadline.
  });
  const r = (res.body && (res.body.result || res.body)) || {};
  const needsReview = req.route==='HOLD' || req.route==='WATERMARK';
  console.log('[Worker][DEBUG] post='+post.post_id+' response status='+res.status+' ok='+res.ok+' storage_url='+(r.storage_url||r.clean_storage_url||'null')+' async_submitted='+(r.async_submitted||false)+' compliance_blocked='+(r.compliance_blocked||false));

  // VIDEO: /api/image/generate handles video async internally and returns
  // { async_submitted:true, clean_storage_url: keyframe_url } — park as video_processing.
  // Sweep Video Processing finalizes it when the .mp4 lands via fal webhook.
  if (req.isVideo) {
    if (res.ok) {
      // async_submitted=true  → video queued, keyframe stored as fallback still
      // async_submitted=false → sync video completed, storage_url has the .mp4
      const asyncVideo = r.async_submitted === true;
      const videoUrl = r.storage_url || null;
      await patch(post.post_id, {
        status: asyncVideo ? 'video_processing' : (videoUrl ? 'clean' : 'failed_visual'),
        video_status: asyncVideo ? 'processing' : (videoUrl ? 'completed' : 'failed'),
        ...(videoUrl && !asyncVideo ? { storage_url: videoUrl } : {}),
        route_decision:req.route.toLowerCase(), cco_score:req.score, confidence_score:req.score,
        claimed_at:null, hold_reason: post.hold_reason||null,
        visual_failed: !asyncVideo && !videoUrl,
      });
      return { post_id:post.post_id, kind:'video', action: asyncVideo ? 'submitted' : (videoUrl ? 'clean' : 'failed') };
    }
    await patch(post.post_id, { status:'failed_visual', video_status:'failed', visual_failed:true,
      claimed_at:null, last_error:('video submit '+res.status) });
    return { post_id:post.post_id, kind:'video', action:'failed', status:res.status };
  }

  // IMAGE: storage_url from response, else self-heal via deterministic path.
  let storage_url = r.storage_url || r.clean_storage_url || null;
  if (!storage_url) {
    const cand = SUPABASE_URL+'/storage/v1/object/public/post-images/clients/'+post.brand_id+'/calendars/'+req.month+'/'+post.post_id+'.jpg';
    const head = await http({ method:'GET', url:cand, json:false, timeout:15000 });
    if (head.ok) storage_url = cand;
  }
  const visual_failed = !res.ok || !storage_url;
  await patch(post.post_id, {
    storage_url, status: visual_failed ? 'failed_visual' : 'clean',
    route_decision: req.route.toLowerCase(), cco_score:req.score, confidence_score:req.score,
    watermark: req.route==='WATERMARK', visual_failed, claimed_at:null,
    requires_human_review: needsReview,
    hold_reason: needsReview ? (post.hold_reason||('low_score_'+req.score)) : (post.hold_reason||null),
    ...(visual_failed ? { last_error:('image gen '+res.status) } : {}),
  });
  // Visual QC (GPT-4o vision) — fire-and-forget so it never blocks the 42s deadline.
  // The route writes visual_score + visual_issues back to calendar_posts itself.
  // Only run for successfully generated image posts (not video, not failed).
  if (!visual_failed && !req.isVideo && storage_url) {
    const vqcBody = JSON.stringify({ flow_id:'N8N-V01', brand_id:post.brand_id, payload:{
      image_url: storage_url, post_id: post.post_id,
      chain_id: post.chain_id || undefined,
      visual_brief_en: post.image_prompt_en || undefined,
      content_type: post.content_type || undefined,
      occasion_flags: Array.isArray(post.occasion_flags) ? post.occasion_flags : undefined,
    }});
    // AWAITED — not fire-and-forget. After visual-qc scores the image, we re-call
    // confidence-gate with the real visual score so the composite is fully computed
    // (Visual 35% + Caption 30% + Brand 20% + Occasion 15%). Without this re-call,
    // A01-generated posts always show a partial composite (visual excluded) in admin QA.
    let vqcResult = null;
    try {
      vqcResult = await http({ method:'POST', url: API_HOST+'/api/agents/cco/visual-qc',
        headers:{'Content-Type':'application/json','x-n8n-signature':sign(vqcBody),
                 'x-n8n-request-id':crypto.randomUUID(),'x-n8n-timestamp':new Date().toISOString()},
        body: vqcBody, timeout: 30000 });
    } catch(_) {}
    // Re-call confidence-gate with the visual result so it can compute the full 4-pillar
    // composite and write flags.pillars.visual. Only if visual-qc returned a score.
    const vqcScore = vqcResult && vqcResult.body && (vqcResult.body.visual_score ?? vqcResult.body.result?.visual_score);
    if (typeof vqcScore === 'number') {
      try {
        const ccoResultForPost = [{
          post_id: post.post_id,
          score: typeof post.cco_score === 'number' ? post.cco_score : 0,
          brave_route_flag: post.brave_route_flag || false,
          negpat_flag: post.negpat_flag || 'NONE',
          cultural_flag: post.cultural_flag || false,
          dialect_flag: post.dialect_flag || false,
          issues: Array.isArray(post.cco_issues) ? post.cco_issues : [],
        }];
        const cgBody = JSON.stringify({
          flow_id: 'N8N-V01',
          brand_id: post.brand_id,
          payload: {
            request_type: 'calendar_scheduled',
            trigger_payload: {},
            cco_results: ccoResultForPost,
            visual_qc_results: [{
              post_id: post.post_id,
              visual_score: vqcScore,
              visual_issues: (vqcResult.body.visual_issues || vqcResult.body.result?.visual_issues || []),
              violations: (vqcResult.body.violations || vqcResult.body.result?.violations || []),
            }],
            occasion_flags: Array.isArray(post.occasion_flags) ? post.occasion_flags : [],
          }
        });
        await http({ method:'POST', url: API_HOST+'/api/agents/ceo/confidence-gate',
          headers:{'Content-Type':'application/json','x-n8n-signature':sign(cgBody),
                   'x-n8n-request-id':crypto.randomUUID(),'x-n8n-timestamp':new Date().toISOString()},
          body: cgBody, timeout: 20000 }).catch(()=>{});
      } catch(_) {}
    }
  }
  // QA queue row for flagged-but-generated posts.
  if (!visual_failed && needsReview) {
    await http({ method:'POST', url: SUPABASE_URL+'/rest/v1/qa_review_queue',
      headers:{ apikey:SERVICE_KEY, Authorization:'Bearer '+SERVICE_KEY, 'Content-Type':'application/json', Prefer:'return=minimal' },
      body: JSON.stringify({ brand_id:post.brand_id, post_id:post.post_id, caption_ar:post.caption_ar||null,
        storage_url, cco_score:req.score,
        trigger_reason: req.route==='HOLD' ? (post.hold_reason||('low_score_'+req.score)) : 'watermark_review',
        held_reason: req.route==='HOLD' ? (post.hold_reason||('low_score_'+req.score)) : null,
        flags:{ route:req.route, negpat_flag:post.negpat_flag||'NONE', brave_route_flag:post.brave_route_flag||false,
                held_detail: post.human_gate_detail||null, human_gate_triggers: post.human_gate_triggers||[] },
        status:'pending' }), json:true, timeout:15000 });
  }
  return { post_id:post.post_id, kind:'image', action: visual_failed?'failed':'clean', storage_url };
}

// ── bounded-concurrency pool over all claimed posts ──
const posts = ($input.all()||[]).map(i=>i.json).filter(p=>p && p.post_id);
if (posts.length === 0) return [{ json:{ generated:0 } }];
const results = [];
let cursor = 0;
const START = Date.now();
const DEADLINE_MS = 42000; // stop launching NEW calls at 42s. Budget: 42s + 38s HTTP timeout
                           // + ~2s for the patch-back loop = 82s worst-case IF a call is mid-flight
                           // at deadline. But since we set HTTP timeout=38s, any call started before
                           // t=42s finishes (or errors) by t=80s. The deadline guard runs, patches all
                           // un-started posts back to pending_visual, node exits clean at ~44s.
                           // The reaper (STALE_MINUTES=4) also catches any post claimed but not patched
                           // back within 4 min, providing a second safety net.
const released = [];
async function worker(){
  while(cursor<posts.length){
    if (Date.now() - START > DEADLINE_MS) {
      while (cursor < posts.length) { const j=cursor++; const p=posts[j]; released.push(p.post_id);
        try { await patch(p.post_id, { status:'pending_visual', claimed_at: null }); } catch(_){} }
      return;
    }
    const idx=cursor++;
    try{ results[idx]=await processOne(posts[idx]); }
    catch(e){
      // Unexpected throw from processOne (not an HTTP error — those return {ok:false}).
      // Patch back to pending_visual so the reaper + next cron tick picks it up.
      const p=posts[idx];
      results[idx]={ post_id:p.post_id, action:'error', error:(e&&e.message) };
      try { await patch(p.post_id, { status:'pending_visual', claimed_at:null, last_error:'worker_throw:'+(e&&e.message||'unknown') }); } catch(_){}
    }
  }
}
await Promise.all(Array.from({length: Math.min(CONCURRENCY, posts.length)}, worker));

const clean = results.filter(r=>r&&r.action==='clean').length;
const video = results.filter(r=>r&&r.kind==='video').length;
const failed = results.filter(r=>r&&(r.action==='failed'||r.action==='error')).length;
return [{ json:{ generated: posts.length, clean, video_submitted: video, failed, released: released.length, results } }];

// ── RECONCILE VISUALS (self-heal for posts stuck failed_visual/visual_processing) ──
// For any post whose deterministic Storage asset EXISTS but DB says failed/processing,
// finalize it as clean. Independent of any n8n pairing. Safety net before claiming new.
const SUPABASE_URL='https://redzmrlzhxkkpgcokgvl.supabase.co'; const SERVICE_KEY='eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJlZHptcmx6aHhra3BnY29rZ3ZsIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NzUzMDE5MiwiZXhwIjoyMDkzMTA2MTkyfQ.JK_Vctncdz90VUxnRXVnwysl6P6XgKbJ2-a5Zf3qgpo';
const BUCKET=SUPABASE_URL+'/storage/v1/object/public/post-images/clients/'; const LIMIT=60;
const sget=async(u)=>{ try{const r=await this.helpers.httpRequest({method:'GET',url:u,returnFullResponse:true,json:false,timeout:12000});const c=r&&(r.statusCode||r.status);return c>=200&&c<300;}catch(_){return false;} };
const patch=async(id,f)=>{ try{await this.helpers.httpRequest({method:'PATCH',url:SUPABASE_URL+'/rest/v1/calendar_posts?post_id=eq.'+id,headers:{apikey:SERVICE_KEY,Authorization:'Bearer '+SERVICE_KEY,'Content-Type':'application/json',Prefer:'return=minimal'},body:f,json:true,timeout:15000});return true;}catch(_){return false;} };
let rows=[];
try{ rows=await this.helpers.httpRequest({method:'GET',url:SUPABASE_URL+'/rest/v1/calendar_posts?status=in.(failed_visual,visual_processing)&select=post_id,brand_id,posting_time,format,route_decision,cco_score,hold_reason&order=updated_at.asc&limit='+LIMIT,headers:{apikey:SERVICE_KEY,Authorization:'Bearer '+SERVICE_KEY},json:true,timeout:20000}); }catch(_){ rows=[]; }
if(!Array.isArray(rows)||rows.length===0) return [{json:{reconciled:0}}];
let recovered=0;
for(const p of rows){
  if(!p.brand_id||!p.post_id) continue;
  const month=(p.posting_time||'').substring(0,7)||'2026-06';
  const base=BUCKET+p.brand_id+'/calendars/'+month+'/'+p.post_id;
  const isVideo=p.format==='video';
  const route=(p.route_decision||(typeof p.cco_score==='number'?'clean':'hold')).toUpperCase();
  const needsReview=route==='HOLD'||route==='WATERMARK';
  const score=(typeof p.cco_score==='number')?p.cco_score:null;
  let url=null,fmt='image';
  if(isVideo && await sget(base+'.mp4')){ url=base+'.mp4'; fmt='video'; }
  if(!url){ if(await sget(base+'-clean.jpg')) url=base+'-clean.jpg'; else if(await sget(base+'.jpg')) url=base+'.jpg'; }
  if(!url) continue;
  await patch(p.post_id,{ storage_url:url, status:'clean', format:fmt, format_tier:fmt, media_type:fmt,
    ...(fmt==='video'?{video_status:'completed'}:{}), visual_failed:false, claimed_at:null, last_error:null,
    cco_score:score, confidence_score:score, route_decision:route.toLowerCase(),
    requires_human_review:needsReview, hold_reason: needsReview?(p.hold_reason||('low_score_'+score)):(p.hold_reason||null) });
  recovered++;
}
return [{json:{reconciled:recovered,scanned:rows.length}}];

// Worker: Reap Stale Claims — uses n8n's built-in HTTP helper (no global fetch, inline secrets).
const SUPABASE_URL = 'https://redzmrlzhxkkpgcokgvl.supabase.co';
const SERVICE_KEY  = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJlZHptcmx6aHhra3BnY29rZ3ZsIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NzUzMDE5MiwiZXhwIjoyMDkzMTA2MTkyfQ.JK_Vctncdz90VUxnRXVnwysl6P6XgKbJ2-a5Zf3qgpo';
const STALE_MINUTES = 4;  // MUST exceed a full claim-all drain (≈50 posts ÷ 5 concurrent
                           // × ~25s ≈ 15-20 min). If set too low (was 5), the reaper would
                           // un-claim posts THIS run is still actively generating → the next
                           // cron tick re-claims them → double-generation / wasted cost.
                           // 30 min safely covers a 3-month drain yet still recovers a run
                           // that genuinely died (n8n crash, timeout).
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: SUPABASE_URL + '/rest/v1/rpc/reap_stale_visual_claims',
    headers: { apikey: SERVICE_KEY, Authorization: 'Bearer ' + SERVICE_KEY, 'Content-Type': 'application/json' },
    body: { p_stale_minutes: STALE_MINUTES }, json: true, timeout: 20000,
  });
} catch (e) {} // best-effort; never block the tick
return [{ json: { reaped_tick: true } }];

// Worker: Claim Batch (atomic) — built-in HTTP helper.
const SUPABASE_URL = 'https://redzmrlzhxkkpgcokgvl.supabase.co';
const SERVICE_KEY  = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJlZHptcmx6aHhra3BnY29rZ3ZsIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NzUzMDE5MiwiZXhwIjoyMDkzMTA2MTkyfQ.JK_Vctncdz90VUxnRXVnwysl6P6XgKbJ2-a5Zf3qgpo';
// CLAIM-ALL-THEN-BATCH: grab the WHOLE pending queue in one go (up to BATCH), then
// 'Loop Over Items' (batchSize 5) processes them 5-at-a-time INTERNALLY within this
// single run — looping until every claimed post is done. This means ONE trigger
// drains the entire calendar; you no longer re-trigger per 5. Atomic claim_pending_visual
// prevents two runs grabbing the same post, so no data loss even if cron overlaps.
const BATCH = 10;  // claim the full calendar at once (3 months ≈ 50-60 posts << 200).
                    // The internal Loop Over Items still paces generation 5 concurrently.
let claimed;
try {
  claimed = await this.helpers.httpRequest({
    method: 'POST',
    url: SUPABASE_URL + '/rest/v1/rpc/claim_pending_visual',
    headers: { apikey: SERVICE_KEY, Authorization: 'Bearer ' + SERVICE_KEY, 'Content-Type': 'application/json' },
    body: { p_limit: BATCH }, json: true, timeout: 20000,
  });
} catch (e) { claimed = []; }
const rows = Array.isArray(claimed) ? claimed : [];
// LOOP SENTINEL: never return [] — an empty output stops the chain, so the
// 'More Pending?' IF and Completion Sweep would never run. The sentinel item
// flows through Parallel Generate (filtered out, generated:0) → IF false →
// Completion Sweep. This is what lets ONE trigger drain the whole queue.
if (rows.length === 0) return [{ json: { queue_empty: true } }];
return rows.map(r => ({ json: r }));

// Worker: Sweep Video-Processing (close the async-video loop) — built-in HTTP helper.
// Video renders async (Flux keyframe → Kling/Seedance i2v, 2-5 min). When n8n's
// Execute-Workflow drops the long-running return payload, Apply parks the post as
// 'video_processing'. NOTHING else re-checks those — they'd be stuck forever. This
// node runs every tick and, for each video_processing post:
//   1) HEAD-check the deterministic .mp4 path → if present, finalize as clean video.
//   2) else if within the POLL budget → WAIT one more tick (bump tick counter). We do
//      NOT regenerate — the original Kling/Seedance render is still producing the .mp4;
//      re-submitting would double-bill and start a fresh job that also times out.
//   3) else (poll budget elapsed) → FALLBACK to the keyframe still ({post_id}-kf.jpg)
//      that was uploaded when the render started, so the post is never blank. Only if
//      the keyframe is ALSO missing do we do ONE clean regenerate, then failed_visual.
// A post is NEVER left blank, stuck, or needlessly re-rendered.
const SUPABASE_URL = 'https://redzmrlzhxkkpgcokgvl.supabase.co';
const SERVICE_KEY  = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJlZHptcmx6aHhra3BnY29rZ3ZsIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NzUzMDE5MiwiZXhwIjoyMDkzMTA2MTkyfQ.JK_Vctncdz90VUxnRXVnwysl6P6XgKbJ2-a5Zf3qgpo';
const MAX_VIDEO_POLL_TICKS = 8;  // ~8 cron ticks (~8 min) of POLLING the in-flight render
                                 // before giving up. Kling/Seedance i2v finish in 2-5 min,
                                 // so this comfortably covers a normal render without
                                 // regenerating. We poll, we do NOT re-submit.
const BUCKET = SUPABASE_URL + '/storage/v1/object/public/post-images/clients/';

const sget = async (url) => {
  try { const r = await this.helpers.httpRequest({ method:'GET', url, returnFullResponse:true, json:false, timeout:15000 }); const c = r && (r.statusCode||r.status); return c>=200&&c<300; } catch(_) { return false; }
};
const patch = async (post_id, fields) => {
  try { await this.helpers.httpRequest({ method:'PATCH', url: SUPABASE_URL+'/rest/v1/calendar_posts?post_id=eq.'+post_id, headers:{ apikey:SERVICE_KEY, Authorization:'Bearer '+SERVICE_KEY, 'Content-Type':'application/json', Prefer:'return=minimal' }, body:{ ...fields }, json:true, timeout:15000 }); } catch(_) {}
};

// Pull posts parked in video_processing (limit to keep the tick bounded).
let rows = [];
try {
  rows = await this.helpers.httpRequest({
    method:'GET',
    url: SUPABASE_URL + '/rest/v1/calendar_posts?status=eq.video_processing&select=post_id,brand_id,posting_time,generation_attempt,cco_score,route_decision,hold_reason&order=updated_at.asc&limit=10',
    headers:{ apikey:SERVICE_KEY, Authorization:'Bearer '+SERVICE_KEY }, json:true, timeout:20000,
  });
} catch(_) { rows = []; }
if (!Array.isArray(rows) || rows.length === 0) return [{ json: { swept: 0 } }];

// generation_attempt is used here as a TICK COUNTER (~1 tick/min), NOT a regen count.
// We POLL the same in-flight render; we do NOT regenerate (the first Kling/Seedance
// job is still producing the .mp4 at the deterministic path — regenerating would burn
// cost, start a fresh 5-min job that also times out, and almost never yield a video).
const out = [];
for (const p of rows) {
  const month = (p.posting_time || '').substring(0,7) || '2026-06';
  const base  = BUCKET + p.brand_id + '/calendars/' + month + '/' + p.post_id;
  const ticks = Number(p.generation_attempt) || 0;
  const route = (p.route_decision || 'clean').toUpperCase();
  const needsReview = route === 'HOLD' || route === 'WATERMARK';

  // 1) Did the .mp4 land? → finalize as clean video. (The in-flight render finished.)
  if (await sget(base + '.mp4')) {
    await patch(p.post_id, { storage_url: base+'.mp4', status:'clean', format:'video', format_tier:'video', media_type:'video', video_status:'completed', visual_failed:false, claimed_at:null, requires_human_review: needsReview, last_error:null });
    out.push({ json: { post_id:p.post_id, action:'recovered_video' } }); continue;
  }
  // 2) Still rendering & within the POLL budget → just wait one more tick. Bump the
  //    tick counter; do NOT touch status (stays video_processing) and do NOT regenerate.
  if (ticks < MAX_VIDEO_POLL_TICKS) {
    await patch(p.post_id, { generation_attempt: ticks + 1, video_status:'processing' });
    out.push({ json: { post_id:p.post_id, action:'still_rendering', tick: ticks + 1 } }); continue;
  }
  // 3) Budget elapsed (render genuinely stuck/failed) → FALLBACK to the keyframe still
  //    so the post is never blank. The keyframe was uploaded at the start of the render.
  if (await sget(base + '-kf.jpg')) {
    await patch(p.post_id, { storage_url: base+'-kf.jpg', status:'clean', format:'image', format_tier:'image', media_type:'image', video_status:'failed', visual_failed:false, claimed_at:null, requires_human_review:true, hold_reason: p.hold_reason || 'video_fell_back_to_image', last_error:'video_render_timed_out_after_'+ticks+'_min' });
    out.push({ json: { post_id:p.post_id, action:'fallback_keyframe' } }); continue;
  }
  // 3b) No keyframe either → ONE clean regenerate as a last resort (covers the rare case
  //     where even the keyframe upload failed), then mark failed_visual if that recurs.
  if (ticks < MAX_VIDEO_POLL_TICKS + 1) {
    await patch(p.post_id, { status:'pending_visual', generation_attempt: ticks + 1, video_status:'processing', claimed_at:null });
    out.push({ json: { post_id:p.post_id, action:'regenerate_no_keyframe', tick: ticks + 1 } }); continue;
  }
  await patch(p.post_id, { status:'failed_visual', video_status:'failed', visual_failed:true, claimed_at:null, requires_human_review:true, last_error:'video_and_keyframe_both_missing' });
  out.push({ json: { post_id:p.post_id, action:'failed_visual' } });
}
return out.length ? out : [{ json: { swept: rows.length } }];

